CREATE TABLE app_user (
 id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE,
 password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('student','instructor','admin'))
);
CREATE TABLE auth_token (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
CREATE INDEX token_user_idx ON auth_token(user_id);
CREATE TABLE course (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id VARCHAR(36) NOT NULL REFERENCES app_user(id),
 title VARCHAR(160) NOT NULL, description TEXT NOT NULL, category VARCHAR(80) NOT NULL, subcategory VARCHAR(100),
 price DECIMAL(12,2) NOT NULL CHECK(price>=0), level VARCHAR(20) NOT NULL, duration_hours DOUBLE PRECISION NOT NULL,
 emoji VARCHAR(40) NOT NULL, accent VARCHAR(20) NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE, grade INTEGER,
 rating DOUBLE PRECISION NOT NULL DEFAULT 0
);
CREATE TABLE topic (id VARCHAR(36) PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES course(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, position INTEGER NOT NULL);
CREATE TABLE lesson (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, topic_id VARCHAR(36) NOT NULL REFERENCES topic(id) ON DELETE CASCADE,
 title VARCHAR(160) NOT NULL, minutes INTEGER NOT NULL, kind VARCHAR(10) NOT NULL, duration DOUBLE PRECISION NOT NULL,
 chapters TEXT NOT NULL, file_key VARCHAR(36), file_name VARCHAR(255), content_type VARCHAR(100), position INTEGER NOT NULL
);
CREATE TABLE enrollment (user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), course_id BIGINT NOT NULL REFERENCES course(id) ON DELETE CASCADE, PRIMARY KEY(user_id,course_id));
CREATE TABLE wishlist (user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), course_id BIGINT NOT NULL REFERENCES course(id) ON DELETE CASCADE, PRIMARY KEY(user_id,course_id));
CREATE TABLE progress (user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), lesson_id BIGINT NOT NULL REFERENCES lesson(id) ON DELETE CASCADE, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE teacher (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL UNIQUE REFERENCES app_user(id), subject VARCHAR(80) NOT NULL, bio VARCHAR(1000) NOT NULL, languages VARCHAR(120) NOT NULL, photo_url TEXT);
CREATE TABLE live_slot (id VARCHAR(36) PRIMARY KEY, teacher_id VARCHAR(36) NOT NULL REFERENCES teacher(id), start_at BIGINT NOT NULL, end_at BIGINT NOT NULL, meeting_url VARCHAR(2048) NOT NULL, closed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX live_slot_teacher_idx ON live_slot(teacher_id,start_at);
CREATE TABLE booking (id VARCHAR(36) PRIMARY KEY, slot_id VARCHAR(36) NOT NULL REFERENCES live_slot(id), student_id VARCHAR(36) NOT NULL REFERENCES app_user(id), goals VARCHAR(1000) NOT NULL, timezone VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('confirmed','cancelled')));
CREATE TABLE class_message (id VARCHAR(36) PRIMARY KEY, booking_id VARCHAR(36) NOT NULL REFERENCES booking(id), sender_id VARCHAR(36) NOT NULL REFERENCES app_user(id), text VARCHAR(500) NOT NULL, sent_at BIGINT NOT NULL);
-- A database lock serializes all scheduling writes, including across server instances.
CREATE TABLE schedule_mutex (id INTEGER PRIMARY KEY);
